css:
.dealcall-sim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: linear-gradient(155deg, #0b1f26 0%, #102e38 55%, #0a1a21 100%);
    color: #d6e4e8;
    padding: 28px;
    border-radius: 14px;
    max-width: 1080px;
    margin: 0 auto;
    box-shadow: 0 18px 48px rgba(0,0,0,0.5);
    border: 1px solid rgba(64,196,180,0.18);
}

.dealcall-sim-header {
    text-align: center;
    border-bottom: 1px solid rgba(64,196,180,0.25);
    padding-bottom: 18px;
    margin-bottom: 22px;
}

.dealcall-sim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: #40c4b4;
    background: rgba(64,196,180,0.10);
    border: 1px solid rgba(64,196,180,0.35);
    padding: 4px 14px;
    border-radius: 999px;
    margin-bottom: 12px;
}

.dealcall-sim-header h1 {
    font-size: 2rem;
    font-weight: 700;
    color: #f1f8f9;
    margin: 6px 0 8px;
    letter-spacing: 0.01em;
}

.dealcall-sim-subtitle {
    font-size: 0.96rem;
    color: #93b0b6;
    max-width: 780px;
    margin: 0 auto;
    line-height: 1.5;
}

.dealcall-sim-period-counter {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    justify-content: center;
    font-size: 0.95rem;
    color: #b0c6cb;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 10px;
    padding: 10px 16px;
    margin-bottom: 22px;
}

.dealcall-sim-period-counter #currentDay,
.dealcall-sim-period-counter #maxPeriods {
    font-weight: 700;
    color: #40c4b4;
}

.dealcall-sim-round-name {
    font-weight: 700;
    color: #f1f8f9;
    margin-left: 6px;
    padding-left: 10px;
    border-left: 1px solid rgba(64,196,180,0.4);
}

.dealcall-sim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    color: #7d969c;
    font-style: italic;
}

.dealcall-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}

.dealcall-sim-status-card {
    background: linear-gradient(150deg, #133643 0%, #0d262f 100%);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 18px 16px;
    text-align: center;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.dealcall-sim-status-card:hover {
    transform: translateY(-2px);
    border-color: rgba(64,196,180,0.4);
}

.dealcall-sim-status-card.dealcall-sim-card-primary {
    border-color: rgba(64,196,180,0.55);
    box-shadow: inset 0 0 22px rgba(64,196,180,0.10);
}

.dealcall-sim-status-card.dealcall-sim-card-npv {
    border-color: rgba(120,170,235,0.4);
}

.dealcall-sim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #88a3a9;
    margin-bottom: 8px;
}

.dealcall-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1;
    color: #f1f8f9;
}

.dealcall-sim-card-primary .dealcall-sim-value {
    color: #5fe0cf;
}

.dealcall-sim-card-npv .dealcall-sim-value {
    color: #8fb8f0;
}

.dealcall-sim-sublabel {
    font-size: 0.72rem;
    color: #6f8a90;
    margin-top: 8px;
    line-height: 1.3;
}

.dealcall-sim-briefing {
    display: flex;
    gap: 16px;
    align-items: flex-start;
    background: rgba(64,196,180,0.06);
    border: 1px solid rgba(64,196,180,0.28);
    border-left: 4px solid #40c4b4;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 22px;
}

.dealcall-sim-briefing-icon {
    font-size: 1.6rem;
    line-height: 1;
}

.dealcall-sim-briefing-title {
    font-size: 1.08rem;
    font-weight: 700;
    color: #f1f8f9;
    margin-bottom: 8px;
}

.dealcall-sim-briefing-text {
    font-size: 0.92rem;
    color: #b0c6cb;
    line-height: 1.6;
}

.dealcall-sim-briefing-text strong {
    color: #5fe0cf;
}

.dealcall-sim-briefing-text em {
    color: #cfe0e4;
    font-style: italic;
}

.dealcall-sim-controls {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 22px 24px;
    margin-bottom: 22px;
}

.dealcall-sim-controls h3 {
    font-size: 1.12rem;
    font-weight: 700;
    color: #f1f8f9;
    margin: 0 0 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255,255,255,0.07);
}

.dealcall-sim-panel label {
    display: block;
    font-size: 0.9rem;
    font-weight: 600;
    color: #c5d6da;
    margin: 16px 0 7px;
    line-height: 1.4;
}

.dealcall-sim-panel label:first-child {
    margin-top: 0;
}

.dealcall-sim-container select,
.dealcall-sim-container input[type="number"] {
    width: 100%;
    background-color: #0a1d24;
    color: #ecf5f6;
    border: 1px solid rgba(64,196,180,0.35);
    border-radius: 8px;
    padding: 11px 13px;
    font-size: 0.9rem;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.dealcall-sim-container select:focus,
.dealcall-sim-container input[type="number"]:focus {
    outline: none;
    border-color: #40c4b4;
    box-shadow: 0 0 0 3px rgba(64,196,180,0.18);
}

.dealcall-sim-container select option {
    background-color: #0a1d24;
    color: #ecf5f6;
}

.dealcall-sim-container input[type="range"] {
    width: 100%;
    margin: 6px 0 0;
    accent-color: #40c4b4;
    background: transparent;
    cursor: pointer;
}

.dealcall-sim-range-readout {
    font-size: 0.85rem;
    color: #93b0b6;
    margin-top: 6px;
}

.dealcall-sim-range-readout span:last-child {
    font-weight: 700;
    color: #5fe0cf;
}

.dealcall-sim-container .btn-primary {
    background: linear-gradient(135deg, #40c4b4 0%, #2a9385 100%);
    border: none;
    color: #052028;
    font-weight: 700;
    letter-spacing: 0.02em;
    padding: 12px 26px;
    border-radius: 8px;
    margin-top: 22px;
    box-shadow: 0 6px 18px rgba(64,196,180,0.25);
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.dealcall-sim-container .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 22px rgba(64,196,180,0.40);
    color: #052028;
}

.dealcall-sim-container .btn-outline-secondary {
    margin-top: 22px;
    margin-left: 10px;
    color: #93b0b6;
    border-color: rgba(255,255,255,0.18);
}

.dealcall-sim-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.06);
    color: #d6e4e8;
}

.dealcall-sim-coach {
    background: linear-gradient(150deg, #102b40 0%, #0c1f2d 100%);
    border: 1px solid rgba(120,170,235,0.28);
    border-left: 4px solid #6f9fe0;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 22px;
}

.dealcall-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #8fb8f0;
    font-weight: 700;
    margin-bottom: 8px;
}

.dealcall-sim-coach-body {
    font-size: 0.92rem;
    color: #bcd0e6;
    line-height: 1.6;
}

.dealcall-sim-coach-body strong {
    color: #a9c8f2;
}

.dealcall-sim-coach-body em {
    font-style: italic;
    color: #d0def0;
}

.dealcall-sim-history,
.dealcall-sim-chart {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 22px;
}

.dealcall-sim-history h3,
.dealcall-sim-chart h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #f1f8f9;
    margin: 0 0 14px;
}

.dealcall-sim-container table.table {
    color: #bccbd0;
    margin-bottom: 0;
}

.dealcall-sim-container table.table th {
    color: #40c4b4;
    border-color: rgba(255,255,255,0.1);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.dealcall-sim-container table.table td {
    border-color: rgba(255,255,255,0.06);
    font-size: 0.88rem;
    vertical-align: middle;
}

.dealcall-sim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .dealcall-sim-container {
        padding: 18px;
    }
    .dealcall-sim-header h1 {
        font-size: 1.5rem;
    }
    .dealcall-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .dealcall-sim-value {
        font-size: 2rem;
    }
    .dealcall-sim-period-counter {
        font-size: 0.85rem;
    }
    .dealcall-sim-clock {
        margin-left: 0;
        width: 100%;
        text-align: center;
    }
    .dealcall-sim-briefing {
        flex-direction: column;
        gap: 8px;
    }
    .dealcall-sim-container .btn-outline-secondary {
        margin-left: 0;
        display: block;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.dc-completion { padding: 8px 4px 4px; }
.dc-cm-head { text-align: center; margin-bottom: 16px; }
.dc-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #40c4b4; }
.dc-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #93b0b6; }
.dc-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #f1f8f9; }
.dc-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.dc-cm-yes { background: rgba(64,196,180,0.16); color: #40c4b4; border: 1px solid rgba(64,196,180,0.45); }
.dc-cm-no { background: rgba(255,120,110,0.14); color: #ff8c82; border: 1px solid rgba(255,120,110,0.5); }
.dc-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.dc-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(64,196,180,0.08); border: 1px solid rgba(64,196,180,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.dc-cm-mv { display: block; font-size: 1.35rem; font-weight: 800; color: #40c4b4; }
.dc-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #93b0b6; text-transform: uppercase; letter-spacing: 0.03em; }
.dc-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #f1f8f9; }
.dc-cm-insights { margin: 0; padding-left: 20px; }
.dc-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #d6e4e8; }

