                state.domainState = {
                    synergy: 0,            // EUR M run-rate synergy captured vs the 12M floor
                    synergyPotential: 0,   // EUR M deliverable synergy bridge sized in R2 (capture ceiling)
                    talent: 100,           // % of acquired engineers retained (the asset)
                    arrSaved: 0,           // EUR M of the 16M at-risk ARR saved (ship before cliff)
                    npv: 0,                // EUR M deal NPV, net of cost & control premium

                    mode: ``,             // acquire | alliance | build
                    shipsOnTime: false,    // does the capability ship before the renewal cliff?
                    cashOut: 0,            // EUR M committed to the path
                    premiumDiscipline: 0,  // -1 overpaid, 0 neutral, +1 disciplined synergy math
                    revSynClaim: 0,        // claimed revenue synergy (winner’s-curse exposure)
                    costSynClaim: 0,
                    talentProtected: false,// diligence response that protects the architect/team
                    integrationDepth: 50,
                    captureMechanism: ``,
                    walkedAway: false,     // walked / pivoted in R2
                    reversibility: `medium`,

                    synergyHistory: [0],
                    talentHistory: [100],
                    arrHistory: [0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mode: `acquire`,
                    factor: `speed`,
                    revers: `high`,
                    convict: 100,
                    revSyn: 6,
                    costSyn: 3,
                    diligence: `reprice`,
                    call: `adjust`,
                    depth: 0,
                    retention: `package`,
                    bridge: `jointpod`,
                    timeline: 0,
                    stress: `accelerate`,
                    defense: `bridge`,
                    agility: `learned`,
                    compose: 100
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const num = (id) => { const el = document.getElementById(id); return el ? parseInt(el.value, 10) : NaN; };
            const flo = (id) => { const el = document.getElementById(id); return el ? parseFloat(el.value) : NaN; };
            const sel = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                let v;
                if ((v = sel(`modeInput`)) !== null) decisions.mode = v;
                if ((v = sel(`factorInput`)) !== null) decisions.factor = v;
                if ((v = sel(`reversInput`)) !== null) decisions.revers = v;
                decisions.convict = num(`convictInput`);
                if (!Number.isFinite(decisions.convict) || decisions.convict < 0 || decisions.convict > 100) { warn(`warn_range_0_100`); return false; }
            } else if (round === 2) {
                let v;
                decisions.revSyn = flo(`revSynInput`);
                if (!Number.isFinite(decisions.revSyn) || decisions.revSyn < 0 || decisions.revSyn > 20) { warn(`warn_revsyn_range`); return false; }
                decisions.costSyn = flo(`costSynInput`);
                if (!Number.isFinite(decisions.costSyn) || decisions.costSyn < 0 || decisions.costSyn > 12) { warn(`warn_costsyn_range`); return false; }
                if ((v = sel(`diligenceInput`)) !== null) decisions.diligence = v;
                if ((v = sel(`callInput`)) !== null) decisions.call = v;
            } else if (round === 3) {
                let v;
                decisions.depth = num(`depthInput`);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) { warn(`warn_range_0_100`); return false; }
                if ((v = sel(`retentionInput`)) !== null) decisions.retention = v;
                if ((v = sel(`bridgeInput`)) !== null) decisions.bridge = v;
                decisions.timeline = num(`timelineInput`);
                if (!Number.isFinite(decisions.timeline) || decisions.timeline < 0 || decisions.timeline > 100) { warn(`warn_range_0_100`); return false; }
            } else if (round === 4) {
                let v;
                if ((v = sel(`stressInput`)) !== null) decisions.stress = v;
                if ((v = sel(`defenseInput`)) !== null) decisions.defense = v;
                if ((v = sel(`agilityInput`)) !== null) decisions.agility = v;
                decisions.compose = num(`composeInput`);
                if (!Number.isFinite(decisions.compose) || decisions.compose < 0 || decisions.compose > 100) { warn(`warn_range_0_100`); return false; }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let synD = 0, talD = 0, arrD = 0, npvD = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // CHOOSE THE GROWTH MODE. Make-ally-buy against speed, cost, control, reversibility.
                // The cliff is real: acquire/alliance ship in time and save the 16M ARR; build misses it.
                ds.mode = d.mode;
                ds.reversibility = d.revers;
                if (d.mode === `acquire`) {
                    ds.shipsOnTime = true; ds.cashOut = this.ASK_PRICE;
                    arrD += this.AT_RISK_ARR;            // capability now -> customers save
                    talD += 0;                           // but the asset can walk; handled R3
                    coachKey = `coach_r1_acquire`;
                } else if (d.mode === `alliance`) {
                    ds.shipsOnTime = true; ds.cashOut = 25;
                    arrD += this.AT_RISK_ARR;            // co-develop ships in time, saves ARR
                    coachKey = `coach_r1_alliance`;
                } else { // build
                    ds.shipsOnTime = false; ds.cashOut = 35;
                    arrD += 0;                           // ships in 20-24 months -> past the cliff
                    coachKey = `coach_r1_build`;          // Common Error 2: builds past the cliff
                }

                // The deciding factor. Speed-to-cliff is the disciplined call; boldness/cost are the errors.
                // R1 sets the NPV trajectory and the coaching; synergy is sized in R2 and captured in R3.
                if (d.factor === `speed`) { npvD += 4; coachKey = (ds.mode === `build`) ? `coach_r1_build_contradiction` : coachKey; }
                else if (d.factor === `control`) { npvD += 2; if (ds.mode === `alliance`) { npvD -= 3; } } // control points away from alliance
                else if (d.factor === `boldness`) { npvD -= 6; coachKey = `coach_r1_boldness`; }   // Common Error 1
                else { // cost
                    npvD -= 3;
                    if (ds.mode === `acquire`) { coachKey = `coach_r1_cost`; } // ’lowest cash’ contradicts a 95M buy
                }

                // Reversibility weighting builds agility reserve for the R4 shock.
                if (d.revers === `high`) { npvD += 2; }
                else if (d.revers === `low`) { npvD -= 2; }

                // Conviction: total tentativeness stalls; reckless all-in on a weak factor over-commits.
                if (d.convict >= 45 && d.convict <= 75) { npvD += 2; }
                else if (d.convict < 25) { npvD -= 3; }
                else if (d.convict > 90 && (d.factor === `boldness` || d.factor === `cost`)) { npvD -= 3; }

                summaryKey = (ds.shipsOnTime && d.factor === `speed`) ? `sum_r1_good` : (ds.mode === `build` ? `sum_r1_build` : `sum_r1_weak`);

            } else if (round === 2) {
                // VALUE THE DEAL & TEST SYNERGY. Build the synergy bridge; avoid the winner’s curse.
                ds.revSynClaim = d.revSyn;
                ds.costSynClaim = d.costSyn;
                const totalClaim = d.revSyn + d.costSyn;
                // Realistic, credible synergy for this asset lands ~7-11M run-rate. Above ~13 is over-promise.
                // R2 sizes the deliverable bridge (the CEILING on synergy); R3 integration decides how much is captured.
                let bridge;
                if (totalClaim <= 11) {
                    bridge = totalClaim * 1.25;          // disciplined & credible: deliverable, room to clear €12M
                    ds.premiumDiscipline = 1;
                } else if (totalClaim <= 14) {
                    bridge = 13.75 + (totalClaim - 11) * 0.25; // diminishing; some claim is already air
                    ds.premiumDiscipline = 0;
                } else {
                    bridge = 13.5;                       // winner’s curse: claim collapses to reality
                    ds.premiumDiscipline = -1;
                    coachKey = `coach_r2_winnerscurse`;   // Common Error 3
                }
                // Alliance / build can’t reach acquisition-grade synergy (no full IP ownership / late).
                if (ds.mode === `alliance`) bridge *= 0.78;
                if (ds.mode === `build`) bridge *= 0.62;
                ds.synergyPotential = Math.round(bridge * 10) / 10; // ceiling captured in R3
                synD += bridge * 0.3;                    // a sliver realized at signing; the rest depends on integration

                // Diligence finding: the architect built 40% and has no lock-in.
                if (d.diligence === `reprice`) { npvD += 6; talD += 3; ds.talentProtected = true; coachKey = (coachKey === `coach_default`) ? `coach_r2_reprice` : coachKey; }
                else if (d.diligence === `retention`) { npvD += 2; talD += 5; ds.talentProtected = true; }
                else { talD -= 6; npvD -= 4; coachKey = `coach_r2_ignore`; } // Common Error: ignore the key-person risk

                // Go / adjust / walk against the EUR 12M floor.
                if (d.call === `adjust`) {
                    npvD += 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_adjust` : coachKey;
                } else if (d.call === `go`) {
                    // Pay the asking price with no structure -> premium rests on unrealized synergy.
                    if (ds.premiumDiscipline < 1 || (ds.mode === `acquire` && ds.synergyPotential < this.FLOOR)) {
                        npvD -= 12; coachKey = `coach_r2_payask`;
                    } else { npvD -= 2; }
                } else { // walk / pivot
                    ds.walkedAway = true; ds.cashOut = 25;
                    if (ds.mode === `acquire`) { ds.mode = `alliance`; ds.synergyPotential = Math.round(ds.synergyPotential * 0.78 * 10) / 10; }
                    ds.shipsOnTime = true;
                    npvD += 4; coachKey = `coach_r2_walk`;
                }

                summaryKey = (ds.premiumDiscipline >= 0 && d.call !== `go`) ? `sum_r2_good` : (ds.premiumDiscipline < 0 ? `sum_r2_curse` : `sum_r2_weak`);

            } else if (round === 3) {
                // INTEGRATION DEPTH & CULTURE. Deep+fast = synergy on paper but 30-50% attrition that
                // destroys it; full standalone = culture safe but no synergy mechanism. The asset is people.
                ds.integrationDepth = d.depth;
                ds.captureMechanism = d.bridge;

                // Retention / cultural-fit plan sets the attrition baseline.
                let attritionResist; // how much engineer flight the plan absorbs
                if (d.retention === `package`) { attritionResist = 32; talD += 4; }
                else if (d.retention === `autonomy`) { attritionResist = 22; talD += 2; }
                else if (d.retention === `standard`) { attritionResist = 8; talD -= 4; }
                else { attritionResist = 0; talD -= 10; coachKey = `coach_r3_noplan`; }
                if (ds.talentProtected) attritionResist += 8; // R2 earn-out / SPA guarantees compound

                // Depth drives BOTH how much of the bridge gets MOBILIZED and how much attrition it causes.
                // Over-absorption (high depth) loses the engineers; ring-fence (low depth) mobilizes nothing.
                const depth = d.depth;
                let mobilize = 0, attrition = 0;   // mobilize = fraction of the bridge a working mechanism reaches
                if (depth >= 35 && depth <= 65) {
                    mobilize = 0.85; attrition = 14;       // the calibrated point: most of the bridge, protected talent
                    coachKey = (coachKey === `coach_default`) ? `coach_r3_calibrated` : coachKey;
                } else if (depth < 20) {
                    mobilize = 0.18; attrition = 4;        // ring-fenced: culture safe, synergy forfeited
                    coachKey = `coach_r3_ringfence`;        // Common Error 5: over-preserve
                } else if (depth > 80) {
                    mobilize = 1.0; attrition = 44;         // full fast absorption: all the bridge ON PAPER, talent flight
                    coachKey = `coach_r3_absorb`;           // Common Error 4: over-integrate
                } else if (depth < 35) {
                    mobilize = 0.5; attrition = 8;
                } else { // 65-80
                    mobilize = 0.95; attrition = 28;
                }

                // Capture mechanism: a joint pod captures synergy WITHOUT forcing absorption.
                if (d.bridge === `jointpod`) { mobilize += 0.12; attrition -= 6; }
                else if (d.bridge === `api`) { mobilize += 0.02; attrition -= 2; } // safe but thin
                else if (d.bridge === `absorb`) { mobilize += 0.05; attrition += 12; } // fastest synergy, worst flight
                else { mobilize -= 0.25; attrition -= 4; } // ring-fence mechanism: no combination, no synergy

                // Timeline pressure amplifies attrition when depth is already aggressive.
                if (d.timeline > 75) { attrition += 10; if (depth > 65) attrition += 8; }
                else if (d.timeline >= 35 && d.timeline <= 65) { mobilize += 0.05; }
                else if (d.timeline < 20) { mobilize -= 0.1; } // too patient misses the synergy window

                // Net attrition after the retention plan.
                const netAttrition = Math.max(0, attrition - attritionResist);
                talD -= netAttrition;
                if (netAttrition >= 30) coachKey = `coach_r3_attrition`;

                // Synergy CAPTURED = the sized bridge × how much integration mobilized × the talent still there
                // to deliver it. Lose the engineers and even a fully ”integrated” deal captures little — the
                // value bought IS the talent. ds.synergy was seeded with the signing sliver in R2.
                mobilize = Math.max(0, Math.min(1, mobilize));
                const retainedAfter = Math.max(0, Math.min(100, ds.talent + talD));
                const talentFactor = retainedAfter / 100;
                const captured = ds.synergyPotential * mobilize * talentFactor;
                // Add the increment over whatever sliver was already booked, never below 0.
                synD += Math.max(0, captured - ds.synergy);

                summaryKey = (depth >= 35 && depth <= 65 && (d.retention === `package` || d.retention === `autonomy`) && d.bridge === `jointpod`) ? `sum_r3_good` : (depth > 80 ? `sum_r3_absorb` : (depth < 20 ? `sum_r3_ringfence` : `sum_r3_weak`));

            } else if (round === 4) {
                // SYNERGY REALIZATION & BOARD DEFENSE. A live shock tests strategic agility.
                const reversReserve = ds.reversibility === `high` ? 1 : (ds.reversibility === `low` ? -1 : 0);

                if (d.stress === `accelerate`) {
                    // Activate retention triggers + internal successors. Strong IF talent base survived.
                    if (ds.talent >= 60) { talD += 4; npvD += 5; coachKey = `coach_r4_accelerate`; }
                    else { talD += 1; npvD += 1; coachKey = `coach_r4_accelerate_thin`; } // nobody left to accelerate
                } else if (d.stress === `renegotiate`) {
                    npvD += 4; talD += 2; coachKey = `coach_r4_renegotiate`;
                } else if (d.stress === `pivot`) {
                    // Converting/acqui-hiring is right precisely when reversibility was preserved.
                    if (reversReserve >= 0) { npvD += 3; talD += 2; coachKey = `coach_r4_pivot`; }
                    else { npvD -= 5; talD -= 4; coachKey = `coach_r4_pivot_trapped`; } // burned the boats in R1
                } else { // freeze
                    talD -= 16; npvD -= 8; coachKey = `coach_r4_freeze`; // standing still loses the capability/talent
                }

                // Board defense framing. Walking the synergy bridge honestly holds the board.
                if (d.defense === `bridge`) { npvD += 6; }
                else if (d.defense === `strategic`) {
                    if (ds.synergy + synD >= this.FLOOR) { npvD += 1; coachKey = (coachKey === `coach_default`) ? `coach_r4_strategic_ok` : coachKey; }
                    else { npvD -= 8; coachKey = `coach_r4_strategic_short`; } // logic can’t cover a missed floor
                } else { // defend the price
                    npvD -= 10; coachKey = `coach_r4_defendprice`; // arguing 9.5x was fair = the winner’s curse on display
                }

                // Agility reflection (Gomes): mode choice is dominated by time-to-value, not boldness.
                if (d.agility === `learned`) { npvD += 4; }
                else if (d.agility === `price`) { npvD -= 4; }

                // Board composure under pushback.
                const c = d.compose;
                if (c >= 50 && c <= 85) { npvD += 4; }
                else if (c < 30) { npvD -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_rattled` : coachKey; }
                else if (c > 92) { npvD -= 2; } // unflappable reads as not hearing the board

                // Carry-through penalties from earlier rounds resolving at 18 months.
                if (!ds.shipsOnTime) { npvD -= 6; } // build missed the cliff: ARR already lost
                if (ds.premiumDiscipline < 0) { npvD -= 6; }   // the overpay shows up in NPV

                // Final re-gate: synergy is only as real as the engineers left to deliver it at 18 months.
                // Late talent loss (e.g. freezing through the shock) erodes synergy already ”captured” on paper.
                const finalTalent = Math.max(0, Math.min(100, ds.talent + talD));
                if (finalTalent < ds.talent) {
                    const erosion = ds.synergy * (1 - finalTalent / Math.max(1, ds.talent));
                    synD -= erosion;
                }
            }

            // Apply deltas with clamps. Synergy floors at 0; talent and ARR clamped; NPV can go negative.
            ds.synergy = Math.max(0, Math.round((ds.synergy + synD) * 10) / 10);
            ds.talent = Math.max(0, Math.min(100, Math.round(ds.talent + talD)));
            ds.arrSaved = Math.max(0, Math.min(this.AT_RISK_ARR, Math.round((ds.arrSaved + arrD) * 10) / 10));
            ds.npv = Math.round((ds.npv + npvD) * 10) / 10;

            ds.synergyHistory.push(ds.synergy);
            ds.talentHistory.push(ds.talent);
            ds.arrHistory.push(ds.arrSaved);

            const coachMsg = window.mySimulation.t(coachKey);
            this._lastCoachKey = coachKey;
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                synergy: ds.synergy,
                synergyDelta: Math.round(synD * 10) / 10,
                talent: ds.talent,
                arrSaved: ds.arrSaved,
                npv: ds.npv,
                npvDelta: Math.round(npvD * 10) / 10,
                mode: ds.mode,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`synergyDisplay`, `domainState.synergy`, (v) => `€` + (Math.round(v * 10) / 10) + `M`);
            uiManager.bind(`talentDisplay`, `domainState.talent`, (v) => Math.round(v) + `%`);
            uiManager.bind(`arrDisplay`, `domainState.arrSaved`, (v) => `€` + (Math.round(v * 10) / 10) + `M`);
            uiManager.bind(`npvDisplay`, `domainState.npv`, (v) => `€` + (Math.round(v * 10) / 10) + `M`);

            const ranges = [
                [`convictInput`, `convictReadout`],
                [`depthInput`, `depthReadout`],
                [`timelineInput`, `timelineReadout`],
                [`composeInput`, `composeReadout`]
            ];
            ranges.forEach(function(pair) {
                const range = document.getElementById(pair[0]);
                const readout = document.getElementById(pair[1]);
                if (range && readout) {
                    readout.textContent = range.value;
                    range.addEventListener(`input`, function() { readout.textContent = range.value; });
                }
            });
            this._bindLangRepaint();
        }

        getChartConfig() {
            return {
                dealcallChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Synergy Captured (€M)`,
                                data: [],
                                borderColor: `#5fe0cf`,
                                backgroundColor: `rgba(95,224,207,0.15)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#5fe0cf`,
                                yAxisID: `y`
                            },
                            {
                                label: `€12M Floor`,
                                data: [],
                                borderColor: `#e0a35f`,
                                borderWidth: 2,
                                borderDash: [7, 5],
                                fill: false,
                                pointRadius: 0,
                                tension: 0,
                                yAxisID: `y`
                            },
                            {
                                label: `Talent Retained (%)`,
                                data: [],
                                borderColor: `#8fb8f0`,
                                backgroundColor: `rgba(143,184,240,0.06)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#8fb8f0`,
                                yAxisID: `y1`
                            },
                            {
                                label: `ARR Saved (€M)`,
                                data: [],
                                borderColor: `#c089e8`,
                                backgroundColor: `rgba(192,137,232,0.06)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c089e8`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#bccbd0` } },
                            title: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 24, position: `left`, ticks: { color: `#93b0b6` }, grid: { color: `rgba(255,255,255,0.06)` }, title: { display: true, text: `€M`, color: `#93b0b6` } },
                            y1: { beginAtZero: true, max: 100, position: `right`, ticks: { color: `#8fb8f0` }, grid: { drawOnChartArea: false }, title: { display: true, text: `Talent %`, color: `#8fb8f0` } },
                            x: { ticks: { color: `#93b0b6` }, grid: { color: `rgba(255,255,255,0.06)` }, title: { display: true, text: `Round`, color: `#93b0b6` } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.synergyHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            const floorLine = ds.synergyHistory.map(() => this.FLOOR);
            return {
                dealcallChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.synergyHistory },
                        { data: floorLine },
                        { data: ds.talentHistory },
                        { data: ds.arrHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the summary. Weights and
        // the winner’s-curse penalty copied VERBATIM from v1.0.0’s inline getPerformanceSummary block.
        _composite(ds) {
            var synergy = ds.synergy || 0, talent = ds.talent || 0, arr = ds.arrSaved || 0, npv = ds.npv || 0;
            var synScore = Math.min(100, (synergy / this.FLOOR) * 60);
            var npvScore = Math.max(0, Math.min(100, 50 + npv * 1.6));
            var composite = Math.round(synScore * 0.4 + npvScore * 0.25 + talent * 0.2 + (arr / this.AT_RISK_ARR * 100) * 0.15);
            if (ds.premiumDiscipline < 0) composite = Math.max(0, composite - 18);
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const synergy = ds.synergy, talent = ds.talent, arr = ds.arrSaved, npv = ds.npv;

            const floorMet = synergy >= this.FLOOR;
            const talentHeld = talent >= 60;
            const arrSaved = arr >= this.AT_RISK_ARR - 0.5;
            const valueCreating = npv > 0;
            const overpaid = ds.premiumDiscipline < 0; // bought the winner’s curse

            // Composite (0-100) via the shared helper — single source of truth (also written to
            // domainState.performance.overallScore each period for the reporting/grading layer).
            const composite = this._composite(ds);

            // ”Disciplined” requires clearing the floor, holding the talent, creating value AND a clean
            // synergy bridge — a deal won on the winner’s curse is never disciplined, however it photographs.
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_destroyed`;
            if (floorMet && talentHeld && valueCreating && !overpaid && composite >= 72) performanceKey = `grade_disciplined`;
            else if (floorMet && valueCreating && composite >= 56) performanceKey = `grade_fragile`;
            else if (composite >= 42) performanceKey = `grade_clawback`;
            const performance = T(performanceKey);

            const insights = [];
            if (floorMet && talentHeld && valueCreating) insights.push(window.mySimulation.t(`insight_disciplined`));
            else if (!floorMet) insights.push(window.mySimulation.t(`insight_floor`));
            else if (!valueCreating) insights.push(window.mySimulation.t(`insight_value`));
            else insights.push(window.mySimulation.t(`insight_fragile`));

            if (ds.mode === `build` && !ds.shipsOnTime) insights.push(window.mySimulation.t(`insight_cliff`));
            if (ds.premiumDiscipline < 0) insights.push(window.mySimulation.t(`insight_curse`));
            if (talent < 50) insights.push(window.mySimulation.t(`insight_talent`));
            if (ds.integrationDepth > 80) insights.push(window.mySimulation.t(`insight_overintegrate`));
            if (ds.integrationDepth < 20) insights.push(window.mySimulation.t(`insight_overpreserve`));
            if (!arrSaved) insights.push(window.mySimulation.t(`insight_arr`));

            return {
                synergy: synergy,
                floor: this.FLOOR,
                talent: talent,
                arrSaved: arr,
                npv: npv,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                floorMet: floorMet,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var met = !!s.floorMet;
            var badge = met
                ? '<span class="dc-cm-badge dc-cm-yes">' + T('cm_floor_met') + '</span>'
                : '<span class="dc-cm-badge dc-cm-no">' + T('cm_floor_missed') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var npv = Math.round((s.npv || 0) * 10) / 10;
            var npvStr = (npv >= 0 ? '\u20AC' : '\u2212\u20AC') + Math.abs(npv) + 'M';
            var syn = Math.round((s.synergy || 0) * 10) / 10;
            var arr = Math.round((s.arrSaved || 0) * 10) / 10;
            var metrics = ''
                + '<div class="dc-cm-metric"><span class="dc-cm-mv">\u20AC' + syn + 'M</span><span class="dc-cm-ml">' + T('cm_m_synergy') + '</span></div>'
                + '<div class="dc-cm-metric"><span class="dc-cm-mv">' + npvStr + '</span><span class="dc-cm-ml">' + T('cm_m_npv') + '</span></div>'
                + '<div class="dc-cm-metric"><span class="dc-cm-mv">' + Math.round(s.talent || 0) + '%</span><span class="dc-cm-ml">' + T('cm_m_talent') + '</span></div>'
                + '<div class="dc-cm-metric"><span class="dc-cm-mv">\u20AC' + arr + 'M</span><span class="dc-cm-ml">' + T('cm_m_arr') + '</span></div>';
            return ''
                + '<div class="dc-completion">'
                +   '<div class="dc-cm-head">'
                +     '<div class="dc-cm-score">' + score + '<span class="dc-cm-score-max">/100</span></div>'
                +     '<div class="dc-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="dc-cm-metrics">' + metrics + '</div>'
                +   '<div class="dc-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="dc-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.mode === `build` && !ds.shipsOnTime) return window.mySimulation.t(`hint_cliff`);
            if (ds.premiumDiscipline < 0) return window.mySimulation.t(`hint_curse`);
            if (ds.talent < 50) return window.mySimulation.t(`hint_talent`);
            if (ds.integrationDepth > 80) return window.mySimulation.t(`hint_absorb`);
            if (ds.integrationDepth < 20 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_ringfence`);
            if (ds.synergy >= this.FLOOR && ds.talent >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Call`, i18nKey: `col_call` },
                { key: `results.synergy`, label: `Synergy €M`, i18nKey: `col_synergy`, formatter: (v) => `€` + (Math.round(v * 10) / 10) + `M` },
                { key: `results.talent`, label: `Talent %`, i18nKey: `col_talent`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.npv`, label: `NPV €M`, i18nKey: `col_npv`, formatter: (v) => `€` + (Math.round(v * 10) / 10) + `M` }
            ];
        }

        getPresets() { return null; }

        // EQIL 2026-08-20 i18n fix. Resolve the live language from vcI18n, which is
        // the only source of truth in production. The USF SimulationFramework
        // exposes no language, lang or currentLanguage property; testing/usf_shim.js
        // does, which is why earlier offline runs read it and appeared to pass.
        _lang() {
            var norm = function (v) { return String(v).split('-')[0].toLowerCase(); };
            try {
                if (window.vcI18n && window.vcI18n._lang) return norm(window.vcI18n._lang);
                var s = window.mySimulation;
                if (s && s.language) return norm(s.language);
                if (s && s.currentLanguage) return norm(s.currentLanguage);
                if (document.documentElement && document.documentElement.lang) {
                    return norm(document.documentElement.lang);
                }
            } catch (e) {}
            return 'en';
        }

        // EQIL 2026-08-20 i18n fix. applyTranslations only rewrites data-i18n nodes.
        // The briefing body, round name, clock and event alert are written by this
        // adapter, so a mid-session language switch must re-run the render.
        _bindLangRepaint() {
            if (this._langRepaintBound) return;
            this._langRepaintBound = true;
            var self = this;
            var repaint = function () {
                try {
                    var s = window.mySimulation;
                    var st = (s && s.state) ? s.state : { currentPeriod: 1 };
                    self._updateBriefing(st);
                    if (self._lastCoachKey && s && typeof s.t === 'function') {
                        var c = document.getElementById('coachText');
                        if (c) c.innerHTML = s.t(self._lastCoachKey);
                    }
                } catch (e) {}
            };
            try { document.addEventListener('express:langchanged', repaint); } catch (e) {}
            try {
                var s0 = window.mySimulation;
                if (s0 && s0.eventBus && typeof s0.eventBus.on === 'function') {
                    s0.eventBus.on('language:changed', repaint);
                }
            } catch (e) {}
        }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `The Acquisition Call`,
                    subtitle:               `A rival just shipped AI demand-forecasting and signed two of your prospects. Three top-ten customers — €16M of ARR — renew on the condition you ship the same capability by 31 May 2027. The board funds the move with one hard string: deliver €12M of run-rate synergy in 24 months, or the capital is clawed back. Buy, ally, or build — then prove it.`,
                    header_tag:             `11 May 2026 · Fluvento Digital SGPS · Lisbon · Board mandate live`,
